-- 044: „Rauch über dem Ostkamm“ – Fortsetzung der Armbrust-Geschichte (erzeugt von quests/g5_ostkamm.py)
insert into public.quest_templates (id, titel, beschreibung, kurz, art, schwierigkeit, rollen, voraussetzung, def)
values ('g_ostkamm', 'Rauch über dem Ostkamm', 'Kunos Leute schlagen eine Schneise auf euer Tal zu. Diesmal reicht Wachehalten nicht mehr.',
        'Kunos Leute schlagen eine Schneise auf euer Tal zu. Diesmal reicht Wachehalten nicht mehr.', 'haupt', 3, '{}', '{"wissen": "rabenfels_offen"}', $q${"start": "start", "szenen": {"start": {"ort": "dorf", "text": "Seit Tagen hängt eine graue Fahne über dem Ostkamm. Heute Morgen fehlt am Waldrand eine ganze Reihe junger Eichen – über Nacht gefällt, die Stümpfe noch hell. Die Wache am Feuer hat nichts gehört. Am Brunnen redet man von nichts anderem: Kunos Leute kommen näher.", "optionen": [{"text": "Zum Kamm hinaufsteigen und sehen, wie weit sie sind", "weiter": "aufstieg"}, {"tag": "[Spuren lesen]", "text": "Erst die Spuren am Waldrand lesen", "probe": {"id": "spuren", "dc": 13}, "erfolg": {"text": "Die Holzfäller kommen nicht über den Weg, sondern durch die alte Rinne am Bach – ein Pfad, den kaum noch jemand kennt. Man könnte ihn sperren. Oder selbst benutzen.", "folgen": {"flag": ["pfad"]}, "weiter": "aufstieg"}, "misserfolg": {"text": "Zu viele Stiefel, zu viel Matsch. Du siehst nur, dass es viele waren.", "weiter": "aufstieg"}}]}, "aufstieg": {"ort": "wald", "text": "Du steigst durch den Wald zum Ostkamm hinauf. Je höher du kommst, desto dichter der Rauch.", "reise": {"text": "Du steigst zum Ostkamm hinauf.", "minuten": 240, "weiter": "kamm"}}, "kamm": {"ort": "wald", "text": "Der Meiler steht nicht mehr allein. Drei weitere qualmen, ein Schuppen ist neu, und zwischen den Zelten stapeln sich Fässer mit dem Zeichen von Turm und Krone. Eine frische Schneise zieht sich den Hang hinab – geradewegs auf euer Tal zu. Vogt Kuno lässt nicht roden. Er lässt einen Weg bauen.", "optionen": [{"text": "Nachts die Meiler löschen und die Fässer zerschlagen", "weiter": "nacht"}, {"text": "Kuno offen zur Rede stellen", "weiter": "kuno"}, {"text": "Umkehren und Verbündete holen", "weiter": "heim_hilfe"}]}, "nacht": {"ort": "feuer", "text": "Du wartest, bis die Feuer im Lager nur noch glimmen. Zwei Wachen, ein Hund, vier Meiler.", "optionen": [{"tag": "[Flink]", "text": "Durch die Rinne zu den Meilern schleichen", "probe": {"id": "flink", "dc": 14, "mod": {"pfad": -3}}, "erfolg": {"text": "Niemand sieht dich kommen.", "weiter": "sabotage"}, "misserfolg": {"text": "Der Hund hebt den Kopf. Dann bellt er.", "weiter": "entdeckt"}}]}, "sabotage": {"ort": "wald", "text": "Wasser zischt in die Glut, Dauben splittern, Pech rinnt ins Moos. Als der Himmel grau wird, stehen Kunos Männer vor kalten Meilern und leeren Fässern – und fluchen in alle Richtungen.", "optionen": [{"text": "Ein Zeichen in den Schuppen ritzen: Dieser Wald ist nicht euer", "weiter": "heim_sieg", "folgen": {"flag": ["zeichen"]}}, {"text": "Unerkannt verschwinden", "weiter": "heim_sieg"}]}, "entdeckt": {"ort": "wald", "gefahr": true, "text": "Fackeln flammen auf. „Da! Am Meiler!“ Kunos Leute kommen von allen Seiten.", "optionen": [], "minispiel": {"art": "kampf", "titel": "Flucht vom Ostkamm", "text": "Schlag dich durch, bis der Wald dich verschluckt.", "dauer": 420, "schwer": 2, "gegner": "banditen", "kampfort": "wald", "erfolg": {"text": "Du brichst durch ihre Reihe und verschwindest zwischen den Stämmen. Hinter dir brennt ein Meiler – nicht so, wie Kuno es wollte.", "folgen": {"flag": ["kampf"]}, "weiter": "heim_sieg"}, "misserfolg": {"text": "Ein Kolben trifft dich an der Schläfe. Du kommst im Unterholz zu dir, allein, blutend – aber frei.", "folgen": {"gefahr": 2}, "weiter": "heim_flucht"}}}, "kuno": {"ort": "wald", "text": "Kuno empfängt dich vor seinem Zelt, den roten Mantel um die Schultern. „Du schon wieder.“ Er deutet auf die Schneise. „Mein Herr will Holz. Viel Holz. Ihr habt Wald. Also – was bietest du, bevor ich ihn mir nehme?“", "optionen": [{"tag": "[Feilschen]", "text": "„Holz aus dem Windbruch, Jahr für Jahr – dafür bleibt der Hang stehen.“", "probe": {"id": "feilschen", "dc": 15}, "erfolg": {"text": "Kuno rechnet laut. Dann schlägt er ein. „Windbruch. Aber jede Fuhre pünktlich, sonst komme ich selbst.“", "weiter": "heim_handel"}, "misserfolg": {"text": "„Windbruch? Dafür baue ich keinen Weg.“", "weiter": "kuno_droht"}}, {"tag": "[Einschüchtern]", "text": "„Wir sind nicht mehr allein. Hinter uns stehen andere Dörfer – und sie wissen, wer ihr seid.“", "probe": {"id": "einschuechtern", "dc": 16}, "erfolg": {"text": "Zum ersten Mal sieht Kuno unsicher aus. „Bis zum Kamm“, knurrt er. „Keinen Schritt weiter. Bis mein Herr entscheidet.“", "weiter": "heim_rueckzug"}, "misserfolg": {"text": "Kuno lacht. „Dann sollen sie kommen.“", "weiter": "kuno_droht"}}, {"text": "Die Urkunde von Moosherz vorzeigen", "weiter": "urkunde", "wenn": {"wissen": "moosherz"}}]}, "urkunde": {"ort": "wald", "text": "Kuno liest die Abschrift zweimal. „Eine Urkunde der alten Herrin. Mein Herr fürchtet nichts so sehr wie einen Streit vor dem König.“ Er rollt das Papier zusammen und gibt es dir zurück. „Wir bleiben jenseits des Kamms. Fürs Erste.“", "optionen": [{"text": "Heimkehren", "weiter": "heim_rueckzug"}]}, "kuno_droht": {"ort": "wald", "text": "„Geh nach Hause und sag deinen Bauern, sie sollen ihre Äxte schärfen. Wenn der Weg fertig ist, kommen wir.“", "optionen": [{"text": "Gehen – und das Tal vorbereiten", "weiter": "heim_hilfe"}]}, "heim_hilfe": {"ort": "wald", "text": "Du machst dich auf den Rückweg. Jede Stunde zählt.", "reise": {"text": "Du eilst ins Tal.", "minuten": 240, "weiter": "rat"}}, "rat": {"ort": "dorf", "text": "Im Langhaus ist kein Platz mehr frei. Du erzählst von der Schneise, den Fässern, Kunos Worten. Dann wird es still. Alle sehen dich an. „Wen holen wir?“", "optionen": [{"text": "Bero und die Furtenauer", "weiter": "aufgebot", "wenn": {"wissen": "bero"}, "folgen": {"flag": ["furtenau"]}}, {"text": "Harrek und seine Söldner vom Steg", "weiter": "aufgebot", "wenn": {"wissen": "harrek"}, "folgen": {"flag": ["harrek"]}}, {"text": "Alle, die eine Axt halten können", "weiter": "aufgebot"}, {"text": "Niemanden. Wir verteidigen nur das Dorf.", "weiter": "ende_wall"}]}, "aufgebot": {"ort": "dorf", "text": "Am Morgen steht ein bunter Haufen am Waldrand: Holzfäller mit Äxten, Hirten mit Schleudern, die Schmiedin mit einem Hammer. Keiner von ihnen ist ein Krieger. Alle sind gekommen.", "optionen": [{"text": "Zum Kamm hinauf", "weiter": "zug"}]}, "zug": {"ort": "wald", "text": "Ihr steigt gemeinsam zum Kamm hinauf, nicht als Spione, sondern als Menge.", "reise": {"text": "Ihr zieht zum Ostkamm.", "minuten": 240, "weiter": "schlacht"}}, "schlacht": {"ort": "wald", "gefahr": true, "text": "Kunos Männer haben euch kommen sehen. Armbrüste hinter Holzstapeln, ein Graben quer über die Schneise.", "optionen": [], "minispiel": {"art": "kampf", "modus": "marsch", "titel": "Die Schlacht um die Schneise", "text": "Kämpft euch bis zu den Meilern durch.", "dauer": 900, "schwer": 3, "gegner": "banditen", "kampfort": "wald", "erfolg": {"text": "Der Graben fällt, dann die Holzstapel. Als Kuno sieht, dass seine Leute laufen, läuft er mit.", "weiter": "ende_befreit"}, "misserfolg": {"text": "Die Bolzen sind zu viele. Ihr müsst zurück, schleppt eure Verwundeten den Hang hinab.", "folgen": {"gefahr": 1}, "weiter": "ende_zurueck"}}}, "heim_sieg": {"ort": "wald", "text": "Im ersten Licht steigst du ins Tal hinab.", "reise": {"text": "Du gehst nach Hause.", "minuten": 240, "weiter": "ende_sabotage"}}, "heim_rueckzug": {"ort": "wald", "text": "Mit Kunos Wort im Rücken gehst du heim.", "reise": {"text": "Du gehst nach Hause.", "minuten": 240, "weiter": "ende_rueckzug"}}, "heim_handel": {"ort": "wald", "text": "Mit einem Handschlag, der nach Pech riecht, gehst du heim.", "reise": {"text": "Du gehst nach Hause.", "minuten": 240, "weiter": "ende_handel"}}, "heim_flucht": {"ort": "wald", "text": "Humpelnd suchst du den Weg nach Hause.", "reise": {"text": "Du gehst nach Hause.", "minuten": 240, "weiter": "ende_flucht"}}, "ende_sabotage": {"ort": "dorf", "ende": true, "text": "Eine Woche lang steigt kein Rauch über dem Ostkamm auf. Dann zieht Kunos Lager weiter nach Osten. Niemand im Tal weiß genau, warum – aber alle wissen, wem sie es verdanken.", "folgen": {"dorf": {"holz": 15, "stimmung": 8}, "chronik": ["ostkamm_sabotage", "Ich habe Kunos Meiler am Ostkamm in einer Nacht zerstört. Seine Leute sind abgezogen."], "journal": ["rabenfels", "Die Herren von Rabenfels", "Vogt Kuno hat den Ostkamm verlassen, nachdem seine Meiler in einer Nacht zerstört wurden. Ulrich von Rabenfels wird das nicht vergessen."], "beute": {"text": "In einem der Fässer lag etwas, das nicht nach Pech roch.", "stufe": 3, "chance": 0.6}}}, "ende_rueckzug": {"ort": "dorf", "ende": true, "text": "Die Schneise wächst nicht weiter. Am Kamm qualmt es noch, aber es ist ihr Wald, nicht eurer. Ein Waffenstillstand, mehr nicht – doch er hält.", "folgen": {"dorf": {"stimmung": 5}, "chronik": ["ostkamm_rueckzug", "Ich habe Vogt Kuno dazu gebracht, jenseits des Ostkamms zu bleiben – ohne einen Tropfen Blut."], "journal": ["rabenfels", "Die Herren von Rabenfels", "Vogt Kuno bleibt jenseits des Ostkamms – vorerst. Ein Waffenstillstand ohne Brief und Siegel."]}}, "ende_handel": {"ort": "dorf", "ende": true, "text": "Jeden Monat rollt eine Fuhre Windbruch zum Kamm. Der Hang bleibt stehen. Manche im Dorf nennen es klug. Andere nennen es Tribut.", "folgen": {"dorf": {"holz": -10, "stimmung": 2}, "chronik": ["ostkamm_handel", "Ich habe mit Vogt Kuno einen Handel geschlossen: Windbruch gegen den Wald am Hang."], "journal": ["rabenfels", "Die Herren von Rabenfels", "Mit Vogt Kuno gilt ein Handel: Windbruch gegen den Wald am Hang. Ob das ein Frieden ist oder ein Tribut, darüber streitet das Dorf."]}}, "ende_flucht": {"ort": "dorf", "ende": true, "text": "Du kommst heim, mit leeren Händen und einer Platzwunde. Am Kamm wird weiter gerodet. Aber jetzt weiß Kuno, dass jemand im Tal sich wehrt.", "folgen": {"dorf": {"stimmung": -2}, "chronik": ["ostkamm_flucht", "Mein Anschlag auf Kunos Lager am Ostkamm ist gescheitert. Ich bin knapp entkommen."]}}, "ende_befreit": {"ort": "dorf", "ende": true, "text": "Am Abend brennen am Ostkamm keine Meiler mehr, sondern Freudenfeuer. Die Schneise wird wieder zuwachsen. Und in den Tälern ringsum erzählt man, dass ein kleines Dorf die Männer von Rabenfels vertrieben hat.", "folgen": {"dorf": {"holz": 25, "stimmung": 10}, "chronik": ["ostkamm_befreit", "Mit dem ganzen Dorf haben wir Vogt Kuno vom Ostkamm vertrieben."], "journal": ["rabenfels", "Die Herren von Rabenfels", "Das Dorf hat Vogt Kuno in offener Schlacht vom Ostkamm vertrieben. Ulrich von Rabenfels hat jetzt einen Grund, uns zu hassen – und einen, uns zu fürchten."], "beute": {"text": "Unter Kunos zurückgelassenen Sachen ist etwas Besonderes.", "stufe": 3, "chance": 0.85}}}, "ende_zurueck": {"ort": "dorf", "ende": true, "text": "Ihr habt verloren, aber nicht alles. Kuno weiß jetzt, dass das Tal kämpft – und baut seine Schneise langsamer. Die Verwundeten heilen. Die Wut bleibt.", "folgen": {"dorf": {"stimmung": -3}, "chronik": ["ostkamm_zurueck", "Wir haben am Ostkamm gegen Kunos Männer gekämpft und mussten zurück."]}}, "ende_wall": {"ort": "dorf", "ende": true, "text": "Ihr hebt einen Graben am Waldrand aus und stellt Pfähle hinein. Kuno kommt nicht – noch nicht. Aber das Dorf schläft hinter seinem Wall ruhiger.", "folgen": {"dorf": {"holz": -10, "stimmung": 3}, "chronik": ["ostkamm_wall", "Wir haben das Dorf gegen die Männer vom Ostkamm befestigt."]}}}}$q$::jsonb)
on conflict (id) do update set titel = excluded.titel, beschreibung = excluded.beschreibung, kurz = excluded.kurz, def = excluded.def, voraussetzung = excluded.voraussetzung;
-- Wer die Armbrust-Geschichte schon offen beendet hat, bekommt den Hinweis nachträglich
insert into public.player_journal (player_id, kind, key, title, text)
select distinct r.player_id, 'auftrag', 'rabenfels_offen', 'Rauch über dem Ostkamm', 'Die Männer von Rabenfels sitzen noch immer am Ostkamm. Wir halten Wache – aber irgendwann muss jemand etwas unternehmen.'
from public.quest_runs r where r.quest_id = 'b_s_armbrust' and r.status = 'fertig' and r.szene in ('ende_wache', 'ende_nichts')
  and not exists (select 1 from public.player_journal j where j.player_id = r.player_id and j.key = 'rabenfels_offen');
